window.DP700_DATA = {"meta":{"title":"DP-700 Interactive Study Simulator","version":"2026.07","questionCount":100,"disclaimer":"Original practice questions created from public Microsoft documentation; not exam dumps or recalled live exam content.","skillsMeasured":[{"name":"Implement and manage an analytics solution","weight":"30–35%"},{"name":"Ingest and transform data","weight":"30–35%"},{"name":"Monitor and optimize an analytics solution","weight":"30–35%"}]},"sources":[{"id":"S1","title":"DP-700 study guide (skills measured as of July 21, 2026)","url":"https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/dp-700"},{"id":"S2","title":"Workspace roles","url":"https://learn.microsoft.com/en-us/fabric/fundamentals/roles-workspaces"},{"id":"S3","title":"OneLake security roles","url":"https://learn.microsoft.com/en-us/fabric/onelake/security/create-manage-roles"},{"id":"S4","title":"Security in Microsoft Fabric","url":"https://learn.microsoft.com/en-us/fabric/security/security-overview"},{"id":"S5","title":"Git integration and deployment pipelines","url":"https://learn.microsoft.com/en-us/fabric/real-time-intelligence/git-deployment-pipelines"},{"id":"S6","title":"Apache Airflow Job workspace settings","url":"https://learn.microsoft.com/en-us/fabric/data-factory/apache-airflow-jobs-workspace-settings"},{"id":"S7","title":"Mirroring overview","url":"https://learn.microsoft.com/en-us/fabric/mirroring/overview"},{"id":"S8","title":"OneLake shortcuts","url":"https://learn.microsoft.com/en-us/fabric/onelake/onelake-shortcuts"},{"id":"S9","title":"Incremental load with a watermark","url":"https://learn.microsoft.com/en-us/fabric/data-factory/tutorial-incremental-copy-data-warehouse-lakehouse"},{"id":"S10","title":"Medallion lakehouse architecture","url":"https://learn.microsoft.com/en-us/fabric/onelake/onelake-medallion-lakehouse-architecture"},{"id":"S11","title":"Lakehouse and Delta tables","url":"https://learn.microsoft.com/en-us/fabric/data-engineering/lakehouse-and-delta-tables"},{"id":"S12","title":"Dimensional modeling in Fabric Warehouse","url":"https://learn.microsoft.com/en-us/fabric/data-warehouse/dimensional-modeling-overview"},{"id":"S13","title":"Eventstreams overview","url":"https://learn.microsoft.com/en-us/fabric/real-time-intelligence/event-streams/overview"},{"id":"S14","title":"Eventstream with Spark Structured Streaming","url":"https://learn.microsoft.com/en-us/fabric/data-engineering/notebook-with-event-stream"},{"id":"S15","title":"Monitoring hub","url":"https://learn.microsoft.com/en-us/fabric/admin/monitoring-hub"},{"id":"S16","title":"Troubleshoot Fabric Spark jobs","url":"https://learn.microsoft.com/en-us/fabric/data-engineering/troubleshoot-spark"},{"id":"S17","title":"Delta table maintenance","url":"https://learn.microsoft.com/en-us/fabric/data-engineering/delta-lake-table-maintenance"},{"id":"S18","title":"V-Order optimization","url":"https://learn.microsoft.com/en-us/fabric/data-engineering/delta-optimization-and-v-order"},{"id":"S19","title":"Warehouse performance guidelines","url":"https://learn.microsoft.com/en-us/fabric/data-warehouse/guidelines-warehouse-performance"},{"id":"S20","title":"Track user activities with audit logs","url":"https://learn.microsoft.com/en-us/fabric/admin/track-user-activities"},{"id":"S21","title":"Endorsement overview","url":"https://learn.microsoft.com/en-us/fabric/governance/endorsement-overview"},{"id":"S22","title":"Sensitivity labels in Fabric","url":"https://learn.microsoft.com/en-us/fabric/governance/information-protection"},{"id":"S23","title":"Dynamic data masking","url":"https://learn.microsoft.com/en-us/fabric/data-warehouse/dynamic-data-masking"},{"id":"S24","title":"Query acceleration over OneLake shortcuts","url":"https://learn.microsoft.com/en-us/fabric/real-time-intelligence/query-acceleration"},{"id":"S25","title":"OneLake availability for Eventhouse","url":"https://learn.microsoft.com/en-us/fabric/real-time-intelligence/event-house-onelake-availability"},{"id":"S26","title":"Deployment pipelines","url":"https://learn.microsoft.com/en-us/fabric/cicd/deployment-pipelines/get-started-with-deployment-pipelines"},{"id":"S27","title":"Fast Copy in Dataflow Gen2","url":"https://learn.microsoft.com/en-us/fabric/data-factory/dataflows-gen2-fast-copy"},{"id":"S28","title":"Resource profiles","url":"https://learn.microsoft.com/en-us/fabric/data-engineering/configure-resource-profile-configurations"},{"id":"S29","title":"Copy Job","url":"https://learn.microsoft.com/en-us/fabric/data-factory/quickstart-copy-job"},{"id":"S30","title":"SCD Type 1","url":"https://learn.microsoft.com/en-us/fabric/data-factory/slowly-changing-dimension-type-one"},{"id":"S31","title":"Structured Streaming checkpoints","url":"https://learn.microsoft.com/en-us/azure/databricks/structured-streaming/checkpoints"},{"id":"S32","title":"Structured Streaming watermarks","url":"https://learn.microsoft.com/en-us/azure/databricks/structured-streaming/watermarks"},{"id":"S33","title":"Warehouse statistics","url":"https://learn.microsoft.com/en-us/fabric/data-warehouse/statistics"},{"id":"S34","title":"KQL database OneLake shortcuts","url":"https://learn.microsoft.com/en-us/fabric/real-time-intelligence/onelake-shortcuts"},{"id":"S35","title":"Real-Time Intelligence medallion architecture","url":"https://learn.microsoft.com/en-us/fabric/real-time-intelligence/architecture-medallion"},{"id":"S36","title":"Manage and monitor an Eventhouse","url":"https://learn.microsoft.com/en-us/fabric/real-time-intelligence/manage-monitor-eventhouse"},{"id":"S37","title":"Dataflow activity and troubleshooting","url":"https://learn.microsoft.com/en-us/fabric/data-factory/dataflow-activity"},{"id":"S38","title":"Monitor pipeline runs","url":"https://learn.microsoft.com/en-us/fabric/data-factory/monitoring-hub-pipeline-runs"}],"questions":[{"n":1,"title":"Least-privilege workspace role","area":"Security and governance","objective":"Implement workspace-level access controls","question":"A business analyst must see all items in a Fabric workspace and run SQL queries, but must not create, modify, or delete workspace items. Which workspace role is the best fit?","options":["Admin","Viewer","Contributor","Member"],"explanation":"Viewer is the least-privilege workspace role for consuming workspace content. Contributor, Member, and Admin grant authoring capabilities. Data access can still require separate item, SQL, semantic-model, or OneLake permissions depending on the item and access path.","refs":["S2","S4"],"batch":1,"correctIndex":1},{"n":2,"title":"Authoring without access administration","area":"Security and governance","objective":"Implement workspace-level access controls","question":"A data engineer must create and edit Fabric items across a workspace but should not administer workspace membership. Which role is normally most appropriate?","options":["Viewer","Contributor","Member","Admin"],"explanation":"Contributor supports creation and modification of workspace content without the broader workspace-management capabilities associated with Member or Admin. Always validate the exact action against the current role matrix because individual item capabilities can vary.","refs":["S2"],"batch":1,"correctIndex":1},{"n":3,"title":"Share one item only","area":"Security and governance","objective":"Implement item-level access controls","question":"A user needs access to one lakehouse but must not see the other items in its workspace. What should you do?","options":["Assign the user the Contributor role","Assign the user the Viewer role","Share the lakehouse and grant only the required item permissions","Move the lakehouse to My workspace"],"explanation":"Item sharing grants restricted access without making the user a workspace-role member. A workspace role would expose more workspace content than required, which violates least privilege.","refs":["S4"],"batch":1,"correctIndex":2},{"n":4,"title":"Restrict rows by user identity","area":"Security and governance","objective":"Implement row-level access controls","question":"Sales representatives query the same Warehouse table, but each representative must see only rows for their assigned region. Which control directly implements this requirement?","options":["Row-level security","Column-level security","Dynamic data masking","A sensitivity label"],"explanation":"Row-level security filters rows according to the querying identity and a security predicate. Column-level security restricts columns, dynamic masking changes how values appear, and sensitivity labels classify/protect items rather than filter query rows.","refs":["S4","S23"],"batch":1,"correctIndex":0},{"n":5,"title":"Prevent access to a sensitive column","area":"Security and governance","objective":"Implement column-level and object-level access controls","question":"A support role must be able to query customer names but must not have SELECT access to the national-ID column. Which control is the strongest direct fit?","options":["Dynamic data masking only","Column-level security","A Promoted endorsement","A workspace domain"],"explanation":"Column-level security can deny or omit access to specific columns. Dynamic data masking is useful against accidental exposure, but it does not constitute a complete authorization boundary and can be vulnerable to inference by users who can query the data.","refs":["S4","S23"],"batch":1,"correctIndex":1},{"n":6,"title":"Understand dynamic data masking","area":"Security and governance","objective":"Implement dynamic data masking","question":"What does dynamic data masking change in a Fabric Warehouse?","options":["The stored values in OneLake","The values displayed in query results for nonprivileged users","The table's sensitivity label","The workspace role of the caller"],"explanation":"A masking policy is applied to query results; it does not rewrite the underlying stored values. Privileged users with UNMASK or elevated permissions can see the original values.","refs":["S23"],"batch":1,"correctIndex":1},{"n":7,"title":"Classify sensitive content","area":"Security and governance","objective":"Apply sensitivity labels","question":"You need a classification that can follow protected data downstream and into supported exports. Which Fabric governance feature should you use?","options":["Sensitivity label","Certified endorsement","Workspace role","Pipeline parameter"],"explanation":"Microsoft Purview sensitivity labels classify and protect sensitive content and can propagate through supported downstream paths. Endorsement communicates trust and quality; it is not a data-protection classification.","refs":["S22"],"batch":1,"correctIndex":0},{"n":8,"title":"Promoted versus Certified","area":"Governance","objective":"Endorse items","question":"A dataset has passed the organization's formal review and should be marked as an authoritative, trustworthy item. Which endorsement should be applied?","options":["Promoted","Certified","Confidential","Viewer"],"explanation":"Certified means an organization-authorized reviewer has verified that the item meets quality standards. Promoted is a lighter creator-driven indication that an item is ready to share; Confidential is a sensitivity classification, not an endorsement.","refs":["S21"],"batch":1,"correctIndex":1},{"n":9,"title":"Audit user actions","area":"Governance and compliance","objective":"Implement and use Fabric audit logs","question":"A compliance officer asks who changed a sensitivity label on a Fabric item. Where should you investigate?","options":["Spark UI Stages tab","Microsoft Purview audit log","Deployment pipeline history only","Lakehouse Files folder"],"explanation":"Fabric user activities, including sensitivity-label events, are recorded for audit and can be searched through Microsoft Purview. Spark UI and deployment history answer operational questions, not tenant-wide compliance auditing.","refs":["S20","S22"],"batch":1,"correctIndex":1},{"n":10,"title":"Purpose of Git integration","area":"Lifecycle management","objective":"Configure version control","question":"A team needs branching, commit history, and collaborative version control for supported Fabric items. Which capability should they configure?","options":["Git integration","A Copy Job","OneLake availability","Dynamic data masking"],"explanation":"Git integration synchronizes supported workspace items with a repository so the team can version, branch, merge, and review changes. It is not the same as deploying content between environments.","refs":["S5"],"batch":1,"correctIndex":0},{"n":11,"title":"Promote content across environments","area":"Lifecycle management","objective":"Create and configure deployment pipelines","question":"You need to promote supported Fabric content from development to test and then production. Which feature is designed for this task?","options":["Git integration","Deployment pipelines","Dataflow Gen2 staging","OneLake shortcuts"],"explanation":"Deployment pipelines copy supported content between configured lifecycle stages. Git integration handles source control; the two features are complementary but solve different problems.","refs":["S5","S26"],"batch":1,"correctIndex":1},{"n":12,"title":"Database objects as code","area":"Lifecycle management","objective":"Implement database projects","question":"Developers want tables, views, and other database objects represented as code in a repository and deployed through a controlled process. What artifact pattern best fits?","options":["A SQL database project","A Real-Time dashboard","A sensitivity label","A lakehouse shortcut"],"explanation":"A database project represents the desired database schema as source-controlled code. It supports review and repeatable deployment of database objects and is preferable to uncontrolled manual changes.","refs":["S1"],"batch":1,"correctIndex":0},{"n":13,"title":"Deployment pipeline stages","area":"Lifecycle management","objective":"Create and configure deployment pipelines","question":"Which statement about Fabric deployment pipeline stages is correct?","options":["A pipeline always has exactly three stages","A pipeline can have two to ten stages, and its stage count cannot be changed after creation","Stages are created automatically from Git branches","Only Power BI reports can be deployed"],"explanation":"Development, Test, and Production are the default names, but a pipeline can be created with two to ten stages. The stage structure is defined at creation and is permanent, so it should be planned carefully.","refs":["S26"],"batch":1,"correctIndex":1},{"n":14,"title":"Workload-specific Spark configuration","area":"Workspace and Spark settings","objective":"Configure Spark workspace settings","question":"One notebook requires a different Spark runtime and compute sizing from the workspace default. What should you attach to that notebook?","options":["A Fabric Environment configured for that workload","A sensitivity label","A deployment-pipeline rule","An Eventstream destination"],"explanation":"An Environment can define runtime, libraries, pool, and driver/executor sizing for specific notebooks or Spark job definitions. When item-level customization is allowed, it can override workspace defaults without changing every Spark workload.","refs":["S28"],"batch":1,"correctIndex":0},{"n":15,"title":"Fast Spark session startup","area":"Workspace and Spark settings","objective":"Configure Spark workspace settings","question":"A development team prioritizes very fast Spark session startup and can use the standard pool configuration. Which pool type is the natural first choice?","options":["Starter pool","Custom capacity pool only","Airflow custom pool","Eventhouse"],"explanation":"Starter pools are prewarmed for fast startup and are suited to common development workloads. Custom pools offer more sizing and governance flexibility but can have provisioning or resume latency depending on configuration.","refs":["S1","S28"],"batch":1,"correctIndex":0},{"n":16,"title":"Airflow production pool","area":"Apache Airflow settings","objective":"Configure Apache Airflow workspace settings","question":"A production Airflow workload needs configurable node size, extra workers, autoscaling, and an always-on runtime until manually paused. Which option should you select?","options":["Starter pool","Custom pool","Viewer role","Copy Job"],"explanation":"An Airflow custom pool supports configurable compute, extra nodes, and autoscale and is intended for production-style requirements. The starter pool is convenient for development and automatically deprovisions after inactivity.","refs":["S6"],"batch":1,"correctIndex":1},{"n":17,"title":"Choose an orchestration tool","area":"Orchestration","objective":"Choose between Dataflow Gen2, a pipeline, and a notebook","question":"A workflow must execute a copy, then run a notebook, then call a stored procedure, with dependencies and failure paths. Which Fabric item should coordinate the workflow?","options":["Dataflow Gen2","Data pipeline","Sensitivity label","KQL queryset"],"explanation":"A data pipeline is the orchestration layer for sequencing heterogeneous activities, dependencies, parameters, retries, and failure handling. A Dataflow focuses on low-code transformation, while a notebook focuses on code-based processing.","refs":["S1","S9"],"batch":1,"correctIndex":1},{"n":18,"title":"Reusable low-code transformation","area":"Orchestration and transformation","objective":"Choose between Dataflow Gen2, a pipeline, and a notebook","question":"A citizen data engineer needs a visual Power Query experience to combine, cleanse, and load data from several business sources. Which item is the best fit?","options":["Dataflow Gen2","Deployment pipeline","Eventhouse","Workspace audit log"],"explanation":"Dataflow Gen2 provides a low-code Power Query transformation experience. A data pipeline can invoke a dataflow, but the transformation logic itself is best authored in the dataflow for this scenario.","refs":["S1","S27"],"batch":1,"correctIndex":0},{"n":19,"title":"Complex code-based transformation","area":"Orchestration and transformation","objective":"Choose between Dataflow Gen2, a pipeline, and a notebook","question":"A transformation requires a custom PySpark library, complex DataFrame logic, and programmatic tests. Which item is the best primary implementation surface?","options":["Notebook","Sensitivity label","Deployment pipeline","Promoted endorsement"],"explanation":"Notebooks are appropriate for custom code, Spark libraries, complex transformations, and programmatic validation. The notebook can then be orchestrated from a data pipeline.","refs":["S1","S28"],"batch":1,"correctIndex":0},{"n":20,"title":"Event-based triggering","area":"Orchestration","objective":"Design schedules and event-based triggers","question":"A pipeline should start when a new file arrives rather than at a fixed clock time. Which trigger pattern should you design?","options":["A schedule trigger","An event-based trigger","A manual-only run","A deployment stage"],"explanation":"Event-based triggers react to a qualifying event such as file arrival. A schedule trigger is appropriate when execution must occur at specified times regardless of source events.","refs":["S1"],"batch":1,"correctIndex":1},{"n":21,"title":"Parameterize a reusable pipeline","area":"Orchestration","objective":"Implement parameters and dynamic expressions","question":"The same ingestion pipeline must load 40 source tables whose names and destinations are stored in metadata. What design best avoids creating 40 nearly identical pipelines?","options":["Hard-code every table in a separate pipeline","Use parameters, metadata lookup, iteration, and dynamic expressions","Give every user the Admin role","Create 40 sensitivity labels"],"explanation":"A metadata-driven pipeline reads configuration, iterates over rows, and builds source/destination values dynamically. This is more maintainable and reduces duplicated orchestration logic.","refs":["S1","S9"],"batch":1,"correctIndex":1},{"n":22,"title":"Scope a OneLake role","area":"OneLake security","objective":"Configure and implement OneLake security","question":"A group must read only two approved folders in a lakehouse. Which OneLake security role scope should you choose?","options":["All data","Selected data","Workspace Admin","Unrestricted SQL CONTROL"],"explanation":"Selected data lets you grant access only to specified tables or folders. All data also covers future folders and is broader than the requirement.","refs":["S3"],"batch":1,"correctIndex":1},{"n":23,"title":"OneLake security bypass risk","area":"OneLake security","objective":"Configure and implement OneLake security","question":"A user is assigned a restrictive OneLake security role but is also a workspace Contributor. Why might the restriction not be effective?","options":["Contributors have elevated OneLake write access that overrides restrictive read roles","Sensitivity labels disable OneLake roles","Git integration grants SQL CONTROL","The user needs a KQL queryset"],"explanation":"Admin, Member, and Contributor workspace roles have elevated access and are not the correct identities on which to enforce restrictive OneLake read policies. Use Viewer or shared read-only access when OneLake security must filter the user's data.","refs":["S3","S4"],"batch":1,"correctIndex":0},{"n":24,"title":"Overlapping OneLake roles","area":"OneLake security","objective":"Configure and implement OneLake security","question":"A user belongs to one OneLake role that grants full table access and another role that applies a restrictive row filter. What effective access should you expect?","options":["The most restrictive role always wins","The most permissive access wins","Both roles are ignored","The workspace is automatically deleted"],"explanation":"Overlapping OneLake roles are additive; broader access can override the intended effect of a restrictive role. Keep permissive and restrictive memberships mutually exclusive when enforcing limits.","refs":["S3"],"batch":1,"correctIndex":1},{"n":25,"title":"Separate trust from protection","area":"Governance","objective":"Apply labels and endorse items","question":"A lakehouse is both authoritative and contains highly sensitive data. Which combination best represents these independent requirements?","options":["Certified endorsement plus an appropriate sensitivity label","Contributor role plus a schedule trigger","Promoted endorsement only","A Git branch plus a Copy Job"],"explanation":"Certification communicates organizational trust and quality; the sensitivity label communicates classification and protection. One does not replace the other.","refs":["S21","S22"],"batch":1,"correctIndex":0},{"n":26,"title":"Avoid copying shared data","area":"Data ingestion","objective":"Create and manage OneLake shortcuts","question":"A lakehouse must expose data stored in another supported OneLake location without duplicating the files. What should you create?","options":["A OneLake shortcut","A full Copy activity","A cloned workspace","A sensitivity label"],"explanation":"A shortcut is a reference that makes remote data appear locally without copying it. This reduces duplication and keeps consumers on the source's current data.","refs":["S8"],"batch":2,"correctIndex":0},{"n":27,"title":"Delete a shortcut safely","area":"Data ingestion","objective":"Create and manage OneLake shortcuts","question":"What happens to the target data when you delete a OneLake shortcut?","options":["The target data is deleted","The target data is archived","Only the shortcut is removed; the target remains","The target becomes read-only"],"explanation":"The shortcut and its target are independent objects. Removing the reference does not delete the underlying source files or tables.","refs":["S8"],"batch":2,"correctIndex":2},{"n":28,"title":"Choose Tables or Files","area":"Lakehouse storage","objective":"Create and manage OneLake shortcuts","question":"You are creating a lakehouse shortcut to a Delta table that should be queryable as a managed table by Spark and through the SQL analytics endpoint. Where should the shortcut be created?","options":["At the top level of the Tables section","In any subfolder under Tables","Only in the Files section","In the workspace recycle bin"],"explanation":"Delta table shortcuts belong at the top level of Tables so engines can discover them as tables. Files is appropriate for general folders, unstructured, or semi-structured data. OneLake does not support shortcuts in subdirectories of the Tables folder.","refs":["S8","S11"],"batch":2,"correctIndex":0},{"n":29,"title":"Query a KQL shortcut","area":"KQL and shortcuts","objective":"Create and manage OneLake shortcuts","question":"A OneLake shortcut has been created inside a KQL database. Which KQL function is used to query it?","options":["external_table()","OPENROWSET()","spark.readStream()","COPY INTO"],"explanation":"In a KQL database, the shortcut is exposed as an external table and queried with external_table('ShortcutName'). The other choices belong to different engines or ingestion paths.","refs":["S34"],"batch":2,"correctIndex":0},{"n":30,"title":"Accelerate repeated shortcut queries","area":"Real-Time Intelligence","objective":"Choose between standard and accelerated shortcuts","question":"Analysts repeatedly query recent Delta data through a OneLake shortcut in a KQL database, and latency is too high. Which feature should you evaluate first?","options":["Query acceleration on the shortcut","Dynamic data masking","A full workspace export","Disabling the Delta log"],"explanation":"Query acceleration caches and optimizes shortcut data within a configured period for faster KQL queries. It retains the shortcut pattern rather than requiring a second authoritative copy designed by the user.","refs":["S24","S34"],"batch":2,"correctIndex":0},{"n":31,"title":"Continuously replicate an operational database","area":"Data ingestion","objective":"Implement mirroring","question":"You need a low-maintenance, near-real-time analytical replica of a supported operational database in OneLake. Which Fabric capability is designed for this?","options":["Database mirroring","A daily CSV export","A sensitivity label","A deployment pipeline"],"explanation":"Database mirroring continuously replicates data and metadata from supported operational sources into analytics-ready Delta tables in OneLake without requiring a custom incremental ETL pipeline.","refs":["S7"],"batch":2,"correctIndex":0},{"n":32,"title":"Synchronize metadata without moving data","area":"Data ingestion","objective":"Implement mirroring","question":"An organization wants Fabric to synchronize catalog, schema, and table metadata while the physical data remains in the source platform. Which mirroring approach fits?","options":["Database mirroring","Metadata mirroring","Open mirroring","Full pipeline copy"],"explanation":"Metadata mirroring synchronizes metadata and relies on shortcuts to reference data in place. Database mirroring physically replicates data; open mirroring accepts change files from applications through the open specification.","refs":["S7"],"batch":2,"correctIndex":1},{"n":33,"title":"Custom producer for mirrored changes","area":"Data ingestion","objective":"Implement mirroring","question":"A custom application can emit insert, update, and delete change files in the open Delta-based mirroring specification. Which Fabric approach should be used?","options":["Open mirroring","Metadata mirroring","A Power BI import model","A workspace role"],"explanation":"Open mirroring lets applications write change data to a mirrored database landing zone through a public, Delta-based specification. Fabric then applies those changes to the mirrored tables.","refs":["S7"],"batch":2,"correctIndex":0},{"n":34,"title":"Copy data without transformations","area":"Data ingestion","objective":"Choose an ingestion pattern","question":"A requirement is limited to copying a supported source table to a Fabric destination incrementally. No transformation or multi-step orchestration is required. What is the simplest fit?","options":["Copy Job","A complex notebook","A Real-Time dashboard","A sensitivity label"],"explanation":"Copy Job unifies bulk, incremental, and continuous copy patterns without requiring a pipeline when the task is only data movement. Use a pipeline when you need broader orchestration or dependent activities.","refs":["S29"],"batch":2,"correctIndex":0},{"n":35,"title":"Coordinate several ingestion steps","area":"Data ingestion and orchestration","objective":"Ingest data by using pipelines","question":"A load must perform two lookups, copy a range of changed rows, and update a control table only after a successful copy. Which item should orchestrate these steps?","options":["Data pipeline","Sensitivity label","OneLake catalog domain","Real-Time dashboard"],"explanation":"Pipelines coordinate dependent activities, expressions, success/failure paths, and control-table updates. This is the standard shape of a watermark-based incremental-load workflow.","refs":["S9"],"batch":2,"correctIndex":0},{"n":36,"title":"Low-code business transformations","area":"Batch transformation","objective":"Choose between Dataflows Gen2, notebooks, KQL, and T-SQL","question":"A team is most productive with Power Query and needs repeatable joins, type conversions, filtering, and grouping before loading a lakehouse. Which tool is the best fit?","options":["Dataflow Gen2","Deployment pipeline","Audit log","Workspace role"],"explanation":"Dataflow Gen2 provides the Power Query-based, low-code transformation experience. It is suitable when the required transformations are well expressed in Power Query and the team does not need custom Spark code.","refs":["S27"],"batch":2,"correctIndex":0},{"n":37,"title":"Use Fast Copy correctly","area":"Batch ingestion performance","objective":"Optimize Dataflow Gen2 ingestion","question":"A Dataflow Gen2 query contains several Fast Copy-supported ingestion steps followed by an unsupported Group By. What design can preserve Fast Copy benefits?","options":["Remove all transformations permanently","Stage the supported ingestion in one query and reference it from a second query for the Group By","Convert the workspace to Viewer","Run VACUUM before every refresh"],"explanation":"Split the work so the first query uses Fast Copy into staging, then let the referenced query perform unsupported transformations with an appropriate engine. A single unsupported step can prevent the whole query from using Fast Copy.","refs":["S27"],"batch":2,"correctIndex":1},{"n":38,"title":"Select a watermark column","area":"Incremental loading","objective":"Design and implement incremental loads","question":"Which source column is generally the best watermark for loading inserted and updated rows?","options":["A random description","A reliably increasing last-modified timestamp","A nullable free-text comment","A sensitivity-label ID"],"explanation":"A watermark must let the process identify rows that changed after the previous successful run. A last-modified timestamp or monotonically increasing change key is a common choice when it reliably changes for inserts and updates.","refs":["S9","S29"],"batch":2,"correctIndex":1},{"n":39,"title":"Define incremental boundaries","area":"Incremental loading","objective":"Design and implement incremental loads","question":"The stored old watermark is W_old and the maximum value captured at the start of the run is W_new. Which predicate provides a nonoverlapping range for this run?","options":["watermark >= W_old AND watermark < W_new","watermark > W_old AND watermark <= W_new","watermark = W_old","watermark IS NULL"],"explanation":"The prior successful upper bound should be excluded and the newly captured upper bound included. This prevents the boundary row from being copied twice while ensuring the current high watermark is included.","refs":["S9"],"batch":2,"correctIndex":1},{"n":40,"title":"Commit a watermark safely","area":"Incremental loading","objective":"Design and implement incremental loads","question":"When should the control table be updated from W_old to W_new?","options":["Before the copy starts","Only after the incremental copy succeeds","Whenever the pipeline is opened","Before W_new is calculated"],"explanation":"Advancing the watermark before a successful copy can cause lost data after a failure. Updating it on the success path makes the next run resume after the last committed range.","refs":["S9"],"batch":2,"correctIndex":1},{"n":41,"title":"Bronze layer purpose","area":"Data architecture","objective":"Prepare data using medallion patterns","question":"Which content belongs primarily in the Bronze layer of a medallion architecture?","options":["Raw data preserved as received","Only aggregated executive KPIs","A fully conformed star schema only","Purview audit logs only"],"explanation":"Bronze preserves source fidelity and provides a replayable source of truth. Cleansing, standardization, and deduplication occur later.","refs":["S10"],"batch":2,"correctIndex":0},{"n":42,"title":"Silver layer purpose","area":"Data architecture","objective":"Prepare data using medallion patterns","question":"Which operation most clearly belongs in the Silver layer?","options":["Preserve a byte-for-byte raw source only","Standardize formats and remove duplicates","Publish only final executive aggregates","Manage Pearson VUE appointments"],"explanation":"Silver is the enriched and cleaned layer. Typical work includes validation, standardization, deduplication, matching, and conformance.","refs":["S10"],"batch":2,"correctIndex":1},{"n":43,"title":"Gold layer purpose","area":"Data architecture","objective":"Prepare data using medallion patterns","question":"Which data product is the strongest Gold-layer example?","options":["Unparsed JSON exactly as received","A curated daily-sales table designed for dashboards","An unvalidated landing folder","A raw CDC log"],"explanation":"Gold contains curated, consumption-ready structures such as aggregates, business metrics, dimensional models, and reporting tables.","refs":["S10"],"batch":2,"correctIndex":1},{"n":44,"title":"Default lakehouse table format","area":"Lakehouse storage","objective":"Choose an appropriate data store and format","question":"Which table format is the default and best-integrated format for Fabric Lakehouse tables?","options":["Delta Lake","Plain XML","A proprietary desktop file","Unlogged CSV only"],"explanation":"Fabric Lakehouse uses Delta Lake by default. Delta combines Parquet data files with a transaction log, providing ACID reliability, history, and integration across Fabric engines.","refs":["S11"],"batch":2,"correctIndex":0},{"n":45,"title":"Idempotent upsert","area":"Batch transformation","objective":"Handle inserts and updates","question":"A target Delta table must update matching business keys and insert new keys in one idempotent operation. Which command pattern is most appropriate?","options":["MERGE","VACUUM","DROP TABLE","GRANT UNMASK"],"explanation":"MERGE implements matched and not-matched actions in one transactional upsert pattern. VACUUM cleans unreferenced files and does not apply business changes.","refs":["S10","S11"],"batch":2,"correctIndex":0},{"n":46,"title":"Deterministic deduplication","area":"Data quality","objective":"Handle duplicate data","question":"A Silver table receives multiple rows for the same business key and must keep the row with the newest event timestamp. Which design is best?","options":["Drop an arbitrary duplicate","Rank rows within each business key by timestamp and keep rank 1","Keep every duplicate forever in Gold","Remove the business key"],"explanation":"A deterministic window/rank rule makes the survivor explicit and repeatable. A generic duplicate drop can retain an arbitrary row when records differ.","refs":["S1","S10"],"batch":2,"correctIndex":1},{"n":47,"title":"Preserve data-quality meaning","area":"Data quality","objective":"Handle missing data","question":"A numeric field is missing for some source rows. What should you do before replacing all nulls with zero?","options":["Confirm that zero has the same business meaning as missing","Always use zero because Spark requires it","Delete the Delta log","Grant Admin to every analyst"],"explanation":"Missing and zero often have different semantics. Data-quality handling must follow business rules; possible responses include imputation, an unknown category, quarantine, or preserving null.","refs":["S1","S10"],"batch":2,"correctIndex":0},{"n":48,"title":"Design a star schema","area":"Dimensional modeling","objective":"Prepare data for a dimensional model","question":"In a star schema, where are numeric observations and foreign keys to descriptive entities normally stored?","options":["Fact table","Dimension table","Sensitivity label","Workspace role"],"explanation":"Fact tables store observations or events at a declared grain, together with dimension keys and aggregatable measures. Dimension tables describe entities such as customer, product, and date.","refs":["S12"],"batch":2,"correctIndex":0},{"n":49,"title":"Use a surrogate key","area":"Dimensional modeling","objective":"Prepare data for a dimensional model","question":"Why is a warehouse-generated surrogate key recommended for a dimension?","options":["It isolates the warehouse from changing or conflicting source keys and supports history","It automatically grants workspace access","It replaces the need for a fact grain","It encrypts every column"],"explanation":"A surrogate key provides a stable, efficient warehouse identifier, helps consolidate sources, and enables multiple historical versions of one natural business key in a Type 2 dimension.","refs":["S12"],"batch":2,"correctIndex":0},{"n":50,"title":"Choose an SCD type","area":"Dimensional modeling","objective":"Handle changing dimensions","question":"Customer region changes must be preserved so historical sales remain attributed to the region valid at the time. Which slowly changing dimension approach should you use?","options":["Type 1 overwrite","Type 2 new version row","Delete the customer dimension","Dynamic data masking"],"explanation":"Type 2 inserts a new dimension version, typically with a new surrogate key and validity markers, while retaining the old version. Type 1 overwrites the attribute and loses history.","refs":["S12","S30"],"batch":2,"correctIndex":1},{"n":51,"title":"No-code streaming route","area":"Streaming ingestion","objective":"Process data by using Eventstreams","question":"You must ingest continuously arriving events, apply simple transformations, and route the results to supported Fabric destinations without writing code. Which item should you create?","options":["Eventstream","Deployment pipeline","Database project","Sensitivity label"],"explanation":"Eventstream is Fabric's managed, no-code experience for bringing in events, transforming them, and routing them to destinations. It is distinct from a batch data pipeline.","refs":["S13"],"batch":3,"correctIndex":0},{"n":52,"title":"Eventhouse hierarchy","area":"Real-Time Intelligence","objective":"Choose an appropriate streaming store","question":"Which statement correctly describes Eventhouse organization?","options":["An Eventhouse can contain multiple KQL databases","A KQL database contains multiple workspaces","A lakehouse must contain an Eventhouse","An Eventstream is a workspace role"],"explanation":"Eventhouse is a management and compute boundary that can host multiple KQL databases. A KQL database contains real-time tables and is queried with KQL.","refs":["S36"],"batch":3,"correctIndex":0},{"n":53,"title":"Store high-volume telemetry","area":"Real-Time Intelligence","objective":"Choose an appropriate streaming engine","question":"A solution must ingest high-volume, time-stamped telemetry and support fast interactive filtering, aggregation, and time-series analysis. Which store/query engine is the strongest fit?","options":["Eventhouse with a KQL database","A Word document","A deployment pipeline stage","A sensitivity label"],"explanation":"Eventhouse and KQL are designed for high-volume event, log, telemetry, and time-series analytics. They provide managed ingestion, fast KQL queries, and real-time monitoring capabilities.","refs":["S25","S36"],"batch":3,"correctIndex":0},{"n":54,"title":"Complex custom stream processing","area":"Streaming transformation","objective":"Process data by using Spark Structured Streaming","question":"A streaming workload requires a custom Python library, complex stateful logic, and DataFrame APIs. Which implementation is most suitable?","options":["A Fabric notebook using Spark Structured Streaming","A Promoted endorsement","A workspace Viewer role","A deployment note"],"explanation":"Spark Structured Streaming in a notebook provides code-first DataFrame processing and custom libraries. Eventstream is preferable for no-code patterns; a notebook is appropriate when the transformation logic needs full code control.","refs":["S14"],"batch":3,"correctIndex":0},{"n":55,"title":"Discover an Eventstream in a notebook","area":"Streaming integration","objective":"Process data by using Spark Structured Streaming","question":"How can a Fabric notebook securely obtain the identifiers needed to read an Eventstream without manually storing a connection string?","options":["Add the Eventstream from Real-Time hub and choose Read with Spark","Copy a password into every code cell","Export the workspace audit log","Use a sensitivity label as a credential"],"explanation":"The notebook integration generates the Eventstream item and data-source identifiers needed by the Spark code. This avoids manually managing a connection string in the notebook.","refs":["S14"],"batch":3,"correctIndex":0},{"n":56,"title":"Checkpoint purpose","area":"Spark Structured Streaming","objective":"Process data by using Spark Structured Streaming","question":"What is the primary purpose of a Structured Streaming checkpoint?","options":["Track offsets, commits, and state so the query can recover","Apply a sensitivity label","Create a deployment stage","Replace the event timestamp"],"explanation":"A checkpoint records source offsets, committed micro-batches, query metadata, and state for stateful operations. It enables recovery without starting the stream from scratch.","refs":["S31"],"batch":3,"correctIndex":0},{"n":57,"title":"Checkpoint isolation","area":"Spark Structured Streaming","objective":"Process data by using Spark Structured Streaming","question":"Two independent streaming queries write to different sinks. How should their checkpoint locations be configured?","options":["Both queries should share one checkpoint directory","Each query should use a unique checkpoint location","Neither query should checkpoint","Use the workspace name as the only checkpoint"],"explanation":"A checkpoint identifies one query and contains its offsets, commits, and state. Sharing it between independent queries can corrupt recovery semantics or cause conflicts.","refs":["S31"],"batch":3,"correctIndex":1},{"n":58,"title":"Control state with a watermark","area":"Spark Structured Streaming","objective":"Handle late-arriving streaming data","question":"A windowed aggregation retains state indefinitely and memory usage keeps growing. Which feature should you add to define the tolerated lateness and allow old state to be removed?","options":["Watermark","Sensitivity label","Deployment pipeline","Workspace domain"],"explanation":"A watermark uses an event-time column and a lateness threshold to bound how long state is retained for stateful operations. It prevents unbounded state growth while defining the late-data tradeoff.","refs":["S32"],"batch":3,"correctIndex":0},{"n":59,"title":"Watermark tradeoff","area":"Spark Structured Streaming","objective":"Handle late-arriving streaming data","question":"What is a typical effect of increasing the watermark delay from 10 minutes to 2 hours?","options":["More tolerance for late data but more retained state and potentially higher latency","Less tolerance for late data and less state","The query becomes batch-only","All event timestamps are rewritten"],"explanation":"A longer delay accepts later events but requires the engine to retain state longer. A shorter delay reduces state and latency but increases the chance that very late records are dropped from stateful results.","refs":["S32"],"batch":3,"correctIndex":0},{"n":60,"title":"Tumbling window","area":"Streaming windowing","objective":"Create windowing functions","question":"You need nonoverlapping counts for each fixed five-minute interval. Which window type should you use?","options":["Tumbling window","Hopping window","Session window","Unbounded global window"],"explanation":"Tumbling windows have a fixed duration and do not overlap. Each event belongs to exactly one five-minute bucket.","refs":["S1","S13"],"batch":3,"correctIndex":0},{"n":61,"title":"Hopping window","area":"Streaming windowing","objective":"Create windowing functions","question":"A dashboard needs a 15-minute rolling aggregate recalculated every five minutes, allowing events to contribute to overlapping windows. Which window type is appropriate?","options":["Hopping window","Tumbling window","Session window","A workspace role"],"explanation":"A hopping window has a window size and a smaller hop interval, creating overlapping fixed windows. Tumbling windows do not overlap.","refs":["S1","S13"],"batch":3,"correctIndex":0},{"n":62,"title":"Session window","area":"Streaming windowing","objective":"Create windowing functions","question":"Events should be grouped into a user's activity session, ending when no event arrives for 20 minutes. Which window is the best fit?","options":["Session window","Tumbling window","Hopping window","A Delta VACUUM window"],"explanation":"A session window groups activity separated by an inactivity gap. Its duration is data-dependent rather than a fixed clock interval.","refs":["S1","S13"],"batch":3,"correctIndex":0},{"n":63,"title":"Use event time","area":"Streaming semantics","objective":"Handle late-arriving streaming data","question":"A device event occurred at 10:00 but arrived at Fabric at 10:08. Which timestamp should drive business windows that represent when the event actually happened?","options":["Event time","Processing time only","Workspace creation time","Deployment time"],"explanation":"Event-time windows reflect when events occurred at the source and work with watermarks to handle arrival delay. Processing time reflects when the engine observed the event and can distort time-based business results.","refs":["S32"],"batch":3,"correctIndex":0},{"n":64,"title":"Append-mode finalization","area":"Spark Structured Streaming","objective":"Handle late-arriving streaming data","question":"For a watermarked window aggregation in append mode, when is a final window row normally emitted?","options":["After the watermark passes the window and lateness threshold","Before any event arrives","Only when the workspace is deleted","Whenever a Git commit is created"],"explanation":"Append mode waits until a window can be considered final according to the watermark. Update mode can publish intermediate changes sooner; complete mode rewrites the complete result and does not drop aggregation state in the same way.","refs":["S32"],"batch":3,"correctIndex":0},{"n":65,"title":"Filter events","area":"Eventstream transformation","objective":"Process data by using Eventstreams","question":"An Eventstream should route only events whose temperature exceeds 80. Which transformation should be applied first?","options":["Filter","Expand","Manage fields","Endorsement"],"explanation":"Filter keeps or discards events according to a field condition. It is the direct operation for content-based selection.","refs":["S13"],"batch":3,"correctIndex":0},{"n":66,"title":"Rename and cast fields","area":"Eventstream transformation","objective":"Process data by using Eventstreams","question":"An incoming event field must be renamed and converted from text to a numeric type. Which no-code Eventstream transformation should you use?","options":["Manage fields","Filter","Union","Workspace Admin"],"explanation":"Manage fields is used to add, remove, rename, and change the data type of fields in the stream.","refs":["S13"],"batch":3,"correctIndex":0},{"n":67,"title":"Flatten an array","area":"Eventstream transformation","objective":"Process data by using Eventstreams","question":"Each incoming event contains an array of sensor readings, and downstream processing requires one row per array element. Which transformation is appropriate?","options":["Expand","Filter","Certified","VACUUM"],"explanation":"Expand creates a separate output row for each element in an array, making nested repeated values available for row-based processing.","refs":["S13"],"batch":3,"correctIndex":0},{"n":68,"title":"Windowed stream aggregate","area":"Eventstream transformation","objective":"Process data by using Eventstreams","question":"You need the average temperature by device for every fixed one-minute window. Which Eventstream operation is central to the calculation?","options":["Aggregate with device grouping and a one-minute window","Dynamic data masking","A deployment pipeline","A workspace shortcut"],"explanation":"The Aggregate transformation calculates measures such as average, sum, minimum, and maximum over a configured time window and grouping key.","refs":["S13"],"batch":3,"correctIndex":0},{"n":69,"title":"Join two streams","area":"Eventstream transformation","objective":"Process data by using Eventstreams","question":"Two event inputs share deviceId and must be combined when the keys match. Which transformation describes the requirement?","options":["Join","Expand","Sensitivity label","Copy Job"],"explanation":"A stream join combines records from two streams according to a matching condition. In code-based Structured Streaming, time bounds and watermarks are also important to control join state.","refs":["S13","S32"],"batch":3,"correctIndex":0},{"n":70,"title":"Route by event content","area":"Eventstream routing","objective":"Process data by using Eventstreams","question":"Critical events must be sent to one destination and normal events to another. What design should you use?","options":["Create filtered branches or derived streams and route each to its destination","Send every event to one unfiltered destination","Use a workspace role as a filter","Delete the event timestamp"],"explanation":"Eventstream supports content-based routing by applying filters and sending the resulting streams to different destinations.","refs":["S13"],"batch":3,"correctIndex":0},{"n":71,"title":"Expose KQL data to other engines","area":"Real-Time Intelligence integration","objective":"Choose an interoperability pattern","question":"Data ingested into a KQL database must also be queryable in Delta format by notebooks and other OneLake-aware Fabric engines. What should you enable?","options":["OneLake availability","Dynamic data masking only","A deployment note","A Pearson VUE voucher"],"explanation":"OneLake availability exposes a logical Delta representation of KQL database tables for other Fabric engines. Schema synchronization keeps that representation aligned in near real time.","refs":["S25"],"batch":3,"correctIndex":0},{"n":72,"title":"Query lakehouse data with KQL","area":"Real-Time Intelligence integration","objective":"Choose between native tables and shortcuts","question":"You want fast KQL analytics over existing lakehouse tables while keeping the Eventhouse-facing endpoint read-only. Which capability fits?","options":["Enable the Eventhouse endpoint for the lakehouse","Convert every table to CSV","Remove the Delta log","Assign Viewer to the capacity"],"explanation":"The Eventhouse endpoint mirrors the lakehouse schema into a read-only KQL database view, uses shortcuts and query acceleration, and enables KQL analytics without moving the source tables into a separately managed native copy.","refs":["S24","S25"],"batch":3,"correctIndex":0},{"n":73,"title":"Transform data at KQL ingestion","area":"Eventhouse transformation","objective":"Process data by using KQL","question":"Raw events land in one KQL table, and every newly ingested batch must be transformed into a curated table immediately. Which Eventhouse feature is designed for this pattern?","options":["Update policy","Deployment pipeline","Sensitivity label","Workspace domain"],"explanation":"An update policy applies a query to newly ingested source data and writes the transformed result to a target table. It supports continuous Bronze-to-Silver processing in Real-Time Intelligence.","refs":["S35"],"batch":3,"correctIndex":0},{"n":74,"title":"Precompute a repeated KQL aggregation","area":"Eventhouse optimization","objective":"Optimize Eventhouse queries","question":"A costly KQL aggregation over billions of events is executed repeatedly with the same grouping logic. Which object should you evaluate to maintain the result incrementally?","options":["Materialized view","Sensitivity label","Workspace role","Raw CSV export"],"explanation":"A KQL materialized view maintains a query result incrementally as data arrives, making repeated aggregation queries faster than recomputing the full history each time.","refs":["S35","S36"],"batch":3,"correctIndex":0},{"n":75,"title":"Align retention and cache","area":"Eventhouse optimization","objective":"Optimize Eventhouse performance","question":"An Eventhouse stores 365 days of telemetry, but 95% of queries read only the latest seven days. Which policy design is most sensible?","options":["Keep the required retention while caching the frequently queried hot period","Delete all data after seven days","Cache all 365 days regardless of cost","Disable query monitoring"],"explanation":"Retention answers how long data must exist; caching answers which portion should be kept hot for query performance. These policies should be tuned independently to business retention and access patterns.","refs":["S35","S36"],"batch":3,"correctIndex":0},{"n":76,"title":"Central activity monitoring","area":"Monitoring","objective":"Monitor Fabric items","question":"Where can you see active and recent runs for pipelines, notebooks, Dataflows Gen2, semantic models, Spark job definitions, and other supported Fabric items in one place?","options":["Monitoring hub","Sensitivity-label menu","Deployment note","OneLake recycle bin"],"explanation":"Monitoring hub provides a centralized view of job status, duration, submitter, history, and available error details across supported Fabric item types. Visibility is still limited to items the user can access.","refs":["S15"],"batch":4,"correctIndex":0},{"n":77,"title":"Locate a pipeline failure","area":"Pipeline troubleshooting","objective":"Identify and resolve pipeline errors","question":"A pipeline run failed. What is the best first diagnostic action?","options":["Open the run details and identify the failed activity and its error message","Delete the entire workspace","Grant Admin to every user","Run VACUUM on every table"],"explanation":"Pipeline run details expose the activity-level failure, inputs, outputs, timing, and error text. Diagnose the specific activity before changing capacity, permissions, or data.","refs":["S38"],"batch":4,"correctIndex":0},{"n":78,"title":"Retry from a failed activity","area":"Pipeline troubleshooting","objective":"Identify and resolve pipeline errors","question":"A long pipeline failed at its final activity after all earlier steps completed successfully and are safe to reuse. Which recovery option can reduce unnecessary reprocessing?","options":["Rerun from the failed or selected activity when supported","Delete the pipeline","Change every activity to manual","Remove all dependencies"],"explanation":"Monitoring hub and pipeline run details can support retrying from a failed or selected activity. Use this only when upstream outputs are valid and the workflow's idempotency rules permit it.","refs":["S38"],"batch":4,"correctIndex":0},{"n":79,"title":"Diagnose Dataflow Gen2","area":"Dataflow troubleshooting","objective":"Identify and resolve Dataflow Gen2 errors","question":"A pipeline's Dataflow activity shows only a generic failure. Where should you look for more detailed Dataflow diagnostics?","options":["The Dataflow Gen2 Recent runs experience and downloadable detailed logs","The item's endorsement badge","The workspace description","The Delta VACUUM history only"],"explanation":"The error shown by a pipeline Dataflow activity can be partial. Recent runs inside the Dataflow provides richer diagnostics and logs; gateway scenarios may also require inspecting gateway logs.","refs":["S37"],"batch":4,"correctIndex":0},{"n":80,"title":"Open Spark diagnostics","area":"Notebook troubleshooting","objective":"Identify and resolve notebook errors","question":"A Fabric notebook's Spark job is slow and intermittently fails. From Monitoring hub, which interface provides job, stage, executor, storage, and environment details?","options":["Spark UI","Sensitivity label pane","Deployment pipeline","Power Query navigator"],"explanation":"Spark UI exposes Jobs, Stages, Executors, Storage, and Environment tabs. These views are essential for diagnosing skew, memory pressure, failed executors, and configuration issues.","refs":["S16"],"batch":4,"correctIndex":0},{"n":81,"title":"Monitor Eventhouse ingestion","area":"Eventhouse troubleshooting","objective":"Identify and resolve Eventhouse errors","question":"A KQL database is receiving fewer rows than expected. Which Eventhouse monitoring signal should you inspect?","options":["Ingested-row and ingestion-error metrics for the database","The workspace color theme","The deployment note font","The Pearson VUE order number"],"explanation":"Eventhouse monitoring surfaces ingestion volume and errors by database, helping distinguish source, mapping, format, and ingestion failures from query-only problems.","refs":["S36"],"batch":4,"correctIndex":0},{"n":82,"title":"Troubleshoot an empty Eventstream destination","area":"Eventstream troubleshooting","objective":"Identify and resolve Eventstream errors","question":"An Eventstream is published, but its destination receives no events. Which sequence is the most useful first check?","options":["Verify source activity, preview the stream, validate transformation filters/schema, then inspect destination status","Immediately delete the source","Disable all security in the tenant","Convert the destination to a sensitivity label"],"explanation":"Trace the flow from source to destination. Confirm events enter the stream, ensure filters or field changes are not discarding them, and then inspect destination configuration and health.","refs":["S13"],"batch":4,"correctIndex":0},{"n":83,"title":"Repair a broken shortcut","area":"Shortcut troubleshooting","objective":"Identify and resolve OneLake shortcut errors","question":"A shortcut suddenly fails after the source team reorganized its storage paths. What is the most likely cause?","options":["The target path was moved, renamed, or deleted","The shortcut copied too much data","The Viewer role rewrote the source","The sensitivity label created a new table"],"explanation":"A shortcut is an independent reference to a target path. Moving, renaming, or deleting the target can break that reference, so verify and recreate or update the shortcut against the current target.","refs":["S8"],"batch":4,"correctIndex":0},{"n":84,"title":"Monitor semantic-model refresh","area":"Monitoring","objective":"Monitor semantic model refresh","question":"A scheduled semantic-model refresh fails overnight. Which central Fabric experience can show the failed activity and available details?","options":["Monitoring hub","OneLake shortcut wizard","Git commit history only","Airflow custom pool"],"explanation":"Semantic-model refresh is among the activities surfaced in Monitoring hub. Use the detail pane and item-specific refresh history to continue diagnosis of credentials, gateway, capacity, or source errors.","refs":["S15"],"batch":4,"correctIndex":0},{"n":85,"title":"Operational monitoring versus audit","area":"Monitoring and governance","objective":"Choose the correct monitoring source","question":"You need to know who deleted a Fabric item, not whether its scheduled job succeeded. Which source is more appropriate?","options":["Microsoft Purview audit log","Monitoring hub only","Spark Storage tab","Delta OPTIMIZE history"],"explanation":"Audit logs track user and administrative actions for compliance. Monitoring hub focuses on the health and outcome of item job executions. Choosing the correct telemetry source avoids an incomplete investigation.","refs":["S15","S20"],"batch":4,"correctIndex":0},{"n":86,"title":"Identify Spark data skew","area":"Spark optimization","objective":"Optimize Spark performance","question":"Most tasks in a Spark stage finish quickly, but two tasks process 50 times more input and run much longer. What is the likely problem?","options":["Data skew","A missing sensitivity label","A deployment-stage count error","A cold Power BI export"],"explanation":"Extreme differences in task input size and duration in the Stages tab indicate uneven partition distribution. Mitigations can include better partitioning, salting skewed keys, or Adaptive Query Execution skew handling.","refs":["S16"],"batch":4,"correctIndex":0},{"n":87,"title":"Recognize executor OOM","area":"Spark troubleshooting","objective":"Identify and resolve notebook errors","question":"Several Spark executors terminate with exit code 137 while processing very large partitions. What should you investigate first?","options":["Executor out-of-memory caused by partition size or skew","The item's endorsement","The deployment-pipeline stage names","The audit-log retention"],"explanation":"Exit code 137 commonly indicates OOM. Inspect task sizes and skew, then consider repartitioning, AQE, memory sizing, reducing caching, or changing an inappropriate broadcast.","refs":["S16"],"batch":4,"correctIndex":0},{"n":88,"title":"Avoid driver memory failure","area":"Spark optimization","objective":"Optimize Spark performance","question":"A notebook calls collect() on a 200-million-row DataFrame and the driver crashes. What is the best correction?","options":["Filter or aggregate first, limit interactive results, or write distributed output instead of collecting everything","Increase the font size","Disable Delta transactions","Grant every user UNMASK"],"explanation":"collect() moves all rows to the driver and can exhaust driver memory. Keep large processing distributed and bring back only a small, bounded result.","refs":["S16"],"batch":4,"correctIndex":0},{"n":89,"title":"Cache selectively","area":"Spark optimization","objective":"Optimize Spark performance","question":"Which caching practice is recommended for large Spark DataFrames?","options":["Cache only DataFrames reused multiple times and unpersist them when finished","Cache every intermediate forever","Cache only on the driver with collect()","Never inspect the Storage tab"],"explanation":"Caching saves recomputation only when the data is reused. Unnecessary cached data consumes executor memory and can create OOM pressure; unpersist it when no longer needed.","refs":["S16"],"batch":4,"correctIndex":0},{"n":90,"title":"Increase Spark parallelism","area":"Spark optimization","objective":"Optimize Spark performance","question":"A DataFrame has too few partitions, and each task processes several gigabytes. Which operation should you evaluate to create more, smaller, balanced partitions?","options":["repartition(N)","coalesce(1)","collect()","VACUUM"],"explanation":"repartition can increase partition count and redistribute data, improving parallelism and reducing per-task memory pressure. coalesce is primarily used to reduce partitions and coalesce(1) is usually harmful for large data.","refs":["S16"],"batch":4,"correctIndex":0},{"n":91,"title":"Compact small Delta files","area":"Lakehouse optimization","objective":"Optimize a Lakehouse table","question":"A Delta table contains thousands of small files and scans have excessive file-management overhead. Which operation directly addresses the layout?","options":["OPTIMIZE","VACUUM only","GRANT UNMASK","Create a sensitivity label"],"explanation":"OPTIMIZE compacts small files into fewer, larger files and can improve scan efficiency. VACUUM removes old unreferenced files; it does not perform the main compaction step.","refs":["S17"],"batch":4,"correctIndex":0},{"n":92,"title":"Reclaim Delta storage","area":"Lakehouse optimization","objective":"Optimize a Lakehouse table","question":"After many updates, deletes, and compactions, a Delta table has old unreferenced files beyond the required retention window. Which command reclaims their storage?","options":["VACUUM","MERGE","SELECT","GRANT"],"explanation":"VACUUM permanently removes unreferenced data files older than the retention threshold. Use a dry run and preserve a safe retention window when historical recovery or concurrent readers matter.","refs":["S17"],"batch":4,"correctIndex":0},{"n":93,"title":"Protect time travel","area":"Lakehouse optimization","objective":"Optimize a Lakehouse table","question":"What is the key risk of aggressively shortening the Delta VACUUM retention period?","options":["Older versions may no longer be queryable with time travel","The table automatically becomes XML","All workspace roles become Admin","Git history is deleted"],"explanation":"Time travel depends on historical data files. Once VACUUM deletes files needed by an older version, that version cannot be reconstructed even if the transaction-log history remains.","refs":["S17"],"batch":4,"correctIndex":0},{"n":94,"title":"Choose V-Order","area":"Lakehouse optimization","objective":"Optimize a Lakehouse table","question":"A Delta table is read repeatedly by dashboards and interactive analytics, while write latency is less important. Which write-time optimization should you evaluate?","options":["V-Order","Disabling all statistics","coalesce(1) for every load","Removing the Delta log"],"explanation":"V-Order reorganizes Parquet layout to improve read efficiency across Fabric engines. It can add write overhead, so it is best evaluated for read-heavy rather than strictly write-heavy workloads.","refs":["S18"],"batch":4,"correctIndex":0},{"n":95,"title":"Understand new-workspace defaults","area":"Spark and Lakehouse optimization","objective":"Configure Spark performance","question":"What is the current default resource profile for newly created Fabric workspaces, and how is V-Order typically configured there?","options":["writeHeavy with V-Order disabled","readHeavyForPBI with V-Order always forced","No profile and V-Order required","Airflow custom with V-Order deleted"],"explanation":"New workspaces default to the writeHeavy profile, optimized for ingestion and transformation, with spark.sql.parquet.vorder.default set to false. Choose a read-heavy profile or explicit configuration when the consumption pattern justifies it.","refs":["S18","S28"],"batch":4,"correctIndex":0},{"n":96,"title":"Apply a read-heavy resource profile","area":"Spark optimization","objective":"Optimize Spark performance","question":"A Fabric Spark environment primarily serves repeated analytical reads rather than ingestion. Which profile should you evaluate?","options":["readHeavyForSpark","writeHeavy only","Viewer","Promoted"],"explanation":"readHeavyForSpark is a built-in resource profile tuned for Spark read workloads. Runtime settings can override an environment default when a specific part of a workload needs different behavior.","refs":["S28"],"batch":4,"correctIndex":0},{"n":97,"title":"Improve Warehouse cardinality estimates","area":"Warehouse optimization","objective":"Optimize query performance","question":"A Warehouse query chooses a poor plan after a major data load. Which metadata should you verify is accurate and current?","options":["Column and table statistics","Sensitivity labels","Deployment-stage descriptions","Eventstream destination colors"],"explanation":"The optimizer uses statistics to estimate row counts and costs. Stale or missing statistics can produce poor join choices and plan estimates, especially after large data changes.","refs":["S19","S33"],"batch":4,"correctIndex":0},{"n":98,"title":"Reduce scanned and returned data","area":"Warehouse optimization","objective":"Optimize query performance","question":"Which query rewrite generally reduces I/O and intermediate data size?","options":["Select only required columns and filter rows as early as possible","Use SELECT * everywhere","Convert all strings to varchar(max)","Remove all predicates"],"explanation":"Projecting only needed columns and applying selective predicates early reduces scans, network transfer, memory, and join input. SELECT * and unnecessarily wide strings increase work.","refs":["S19"],"batch":4,"correctIndex":0},{"n":99,"title":"Avoid trickle DML","area":"Warehouse optimization","objective":"Optimize a data warehouse","question":"A workload performs thousands of tiny INSERT transactions into a Fabric Warehouse and query performance degrades. What change is recommended?","options":["Batch the writes or use bulk loading such as COPY INTO","Increase the number of tiny transactions","Disable every background optimization","Store every value as varchar(max)"],"explanation":"Trickle DML creates many small Parquet files and fragmented row groups. Batch-oriented ingestion improves file layout and reduces dependence on later background compaction.","refs":["S19"],"batch":4,"correctIndex":0},{"n":100,"title":"Interpret a slow first query","area":"Warehouse monitoring and optimization","objective":"Optimize query performance","question":"The first execution of a Warehouse query after inactivity is slow, but subsequent executions are much faster with the same plan and data. What is the most likely explanation?","options":["Cold-cache or initialization work on the first execution","Every subsequent query is incorrect","A sensitivity label changed the data","The workspace role compacted the table"],"explanation":"The first query can pay for data caching, statistics generation, or compute initialization. Compare multiple runs and use query insights and DMVs before concluding that the query regressed.","refs":["S19"],"batch":4,"correctIndex":0}]};
